	[1715] = {
		dataList[1830],
		dataList[1831],
		dataList[1832],
		dataList[1833],
		dataList[1834],
		dataList[1835],
		dataList[1836]
	}
}

t_infinite_future_creeps.dataList = dataList

local mt = {
	__index = function(t, key)
		local index = title[key]

		if index then
			return rawget(t, index)
		end
	end
}

for i, v in ipairs(dataList) do
	setmetatable(v, mt)
end

return t_infinite_future_creeps
